void generic_key_without_preparation(const Scene &prepared){
 const auto original=prepared.active().material_bindings->normal_preparation;
 Scene native;auto &o=native.active();o.mesh_active=true;o.painted=original->original_paint->snapshot();o.material_bindings=original->original_material;o.deformation=original->original_deformation;o.appearance=original->original_appearance;
 check(o.material_bindings&&o.material_bindings->normal_frames&&!o.material_bindings->normal_preparation&&!o.painted->normal_projection()&&o.painted->mesh().positions.size()==4,"Generic fixture uses actual retained native4 artist attributes without a normal preparation or image");native.validate();
 const auto unsplit=native.encode();SourceUvBakeInput input;input.paint=o.painted;input.current_material=o.material_bindings;input.current_deformation=o.deformation;input.appearance=o.appearance;input.source_vertices=o.painted->mesh().indices;
 const auto &old=o.painted->mesh();for(auto v:input.source_vertices){input.target.positions.push_back(old.positions[v]);input.target.normals.push_back(old.normals[v]);auto uv=old.uv[v];input.target.uv.push_back({uv[0]*.7f,uv[1]*.7f});input.target.indices.push_back(uint32_t(input.target.indices.size()));}auto result=adopt_source_uv_bake(bake_source_uv(input));o.painted=result.paint;o.material_bindings=result.material_bindings;o.deformation=result.deformation;o.appearance=result.appearance;native.validate();
 check(o.painted->mesh().positions.size()==6&&o.material_bindings->normal_frames->pbr->origin_vertex_count==4&&!o.material_bindings->normal_preparation&&!o.painted->normal_projection(),"Real generic SourceUV split retains original4 frames beside current6 with no dummy normal field");
 const auto exact=native.encode();auto positions=o.painted->mesh().positions;positions[0].z+=.013f;positions[3].z-=.017f;ShapeKeyEdit edit;edit.action=ShapeKeyAction::Replace;edit.target=0;edit.positions=positions;
 Document doc;doc.replace(native);auto endpoint=[&]{if(!doc.wait_asset(std::chrono::seconds(60))||!doc.wait_mesh(std::chrono::seconds(60))||!doc.frame().state->error.empty())throw std::runtime_error("Generic native key endpoint: "+doc.frame().state->error);};endpoint();doc.author_shape(edit);endpoint();auto current=doc.copy_scene();const auto &binding=current.active().material_bindings;
 check(binding->key_derivation&&!binding->normal_preparation&&!current.active().painted->normal_projection()&&!current.active().painted->baked(),"Actual native worker authors universal independent key authority without manufacturing normal images/preparation");
 std::cout<<"GENERIC_PBR_T "<<binding->normal_frames->pbr->tangents.size()<<" MTOON_T "<<binding->normal_frames->mtoon->tangents.size()<<" SOURCE_T "<<o.material_bindings->normal_frames->pbr->tangents.size()<<" DELTA_A "<<current.active().deformation->morphs->targets[0].delta[0].z<<" DELTA_B "<<current.active().deformation->morphs->targets[0].delta[3].z<<" REST_A "<<o.painted->mesh().positions[0].z<<" REST_B "<<o.painted->mesh().positions[3].z<<std::endl;
 check(binding->normal_frames->pbr->tangents.empty()&&binding->normal_frames->mtoon->tangents.empty()&&current.active().deformation->morphs->targets[0].delta[0].z==.013f&&current.active().deformation->morphs->targets[0].delta[3].z==-.017f,"Generic N-only artist frames keep both seam endpoints and never invent tangents");
 const auto encoded=current.encode();check(encoded.at("version")==22&&encoded.at("source_materials").at("version")==10&&encoded.at("source_materials").at("normal_preparations").empty()&&!encoded.contains("normal_sampling"),"Universal material10/Scene22 codec has genuinely absent normal-preparation and sampler tables when unused");
 auto read=Scene::decode(nlohmann::json::from_cbor(nlohmann::json::to_cbor(encoded)));check(read.active().material_bindings->key_derivation&&!read.active().material_bindings->normal_preparation&&read.active().material_bindings->key_derivation->position_domain()->source_frame_basis()->positions.size()==4,"Generic Scene restart replays exact source4 and derived6 with no normal-map owner");
 check(doc.undo()&&doc.copy_scene().encode()==exact&&doc.redo()&&doc.copy_scene().encode()==encoded,"Native universal key publication has one exact full-project Undo/Redo");endpoint();
 ShapeKeyEdit restore;restore.action=ShapeKeyAction::Restore;author_shapekey(read,read.active().id,restore);check(read.encode()==exact,"Generic Restore recovers the complete real pre-key source, paint and rig");
 check(native.encode()==exact&&unsplit.at("version")<22,"Generic authoring preserves both actual prior source documents and their legacy versions");
}
